        if '+' in v:
            v = v[:v.index('+')]

        # Split version and pre-release
        if '-' in v:
            version_part, prerelease_part = v.split('-', 1)
        else:
            version_part = v
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
        else:
            identifiers = None

        return (major, minor, patch, identifiers)

    def compare_prerelease(id1, id2):
        # Both are strings at this point
        is_digit1 = id1.isdigit()
        is_digit2 = id2.isdigit()

        if is_digit1 and is_digit2:
            # Both all-digit: compare numerically
            return int(id1) - int(id2)
        elif is_digit1:
            # id1 is all-digit, id2 is not: id1 sorts before
            return -1
        elif is_digit2:
            # id2 is all-digit, id1 is not: id2 sorts before
            return 1
        else:
            # Neither all-digit: ASCII order
            if id1 < id2:
                return -1
            elif id1 > id2:
                return 1
            else:
                return 0

    def compare_versions(parsed1, parsed2):
        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        # Compare numeric versions
        if major1 != major2:
            return major1 - major2
        if minor1 != minor2:
            return minor1 - minor2
        if patch1 != patch2:
            return patch1 - patch2

        # Handle pre-release versions
        if pre1 is None and pre2 is None:
            return 0
        elif pre1 is None:
            # No pre-release sorts after pre-release
            return 1
        elif pre2 is None:
            return -1
        else:
            # Both have pre-release: compare identifiers
            for i in range(min(len(pre1), len(pre2))):
                cmp = compare_prerelease(pre1[i], pre2[i])
                if cmp != 0:
                    return cmp

            # If all shared identifiers equal, fewer sorts first
            return len(pre1) - len(pre2)

    # Parse all versions with their original indices
    parsed_versions = []
    for idx, v in enumerate(versions):
        parsed = parse_version(v)
        parsed_versions.append((parsed, idx, v))

    # Sort using comparison function, keeping original order for equal versions
    from functools import cmp_to_key
    parsed_versions.sort(key=cmp_to_key(lambda x, y: compare_versions(x[0], y[0]) or (x[1] - y[1])))

    return [v for _, _, v in parsed_versions]

